/**
 * Act Tracker (PoE 1) dataset schema.
 * - Route: generated by `scripts/poe1-act-tracker-data.mjs` from the exile-leveling route (MIT) — never edited by
 *   hand. One step = one instruction; conditional blocks (bandits, league-start extras, trials, Library) are
 *   options a guide profile turns on or off.
 * - Rewards: hand-checked (`rewards.ts`), every entry with its sources and verification.
 * Spec: docs/modules/act-tracker.md
 */

/** How far a fact can be trusted. Shown wherever the fact is shown. */
export type Verification =
  /** From the game itself: game files, or the game's own output in your Client.txt. */
  | "VERIFIED"
  /** A maintained community source (or two agreeing ones). */
  | "COMMUNITY_VERIFIED"
  /** Part of the entry is verified, part is not (the note says which). */
  | "PARTIALLY_VERIFIED"
  | "UNVERIFIED"
  /** Known to be from an older game version. */
  | "OUTDATED"
  /** Sources disagree; never shown as fact. */
  | "CONFLICT";

export type SourceId = "client-log" | "repoe" | "exile-leveling" | "poedb";

export interface Source {
  id: SourceId;
  name: string;
  url: string | null;
  license: string | null;
  /** What it is: game files, the game's own output, or a community source. */
  kind: "game-data" | "game-output" | "community";
}

export interface Provenance {
  sources: SourceId[];
  verification: Verification;
  /** ISO date the entry was last checked against its sources. */
  lastVerified: string;
  /** Game version the check was made for (e.g. "3.30"). */
  gameVersion: string;
  notes?: string;
}

// ---------------------------------------------------------------- route

/** Options of the source route. */
export type RouteFlag = "LEAGUE_START" | "LIBRARY" | "BANDIT_KILL" | "BANDIT_ALIRA" | "BANDIT_KRAITYN" | "BANDIT_OAK";

export type StepKind =
  | "enter" // walk into another area (detected: the area is entered)
  | "waypoint" // travel by waypoint (detected: the target area is entered)
  | "logout" // back to the act town (detected: the town is entered)
  | "portal" // take a town portal
  | "hand-in" // talk to an NPC and take the reward
  | "kill"
  | "quest-item"
  | "trial" // Trial of Ascendancy
  | "labyrinth"
  | "get-waypoint"
  | "crafting"
  | "other";

export interface StepCondition {
  flag: RouteFlag;
  /** `#ifndef`: the block applies when the flag is OFF. */
  negate: boolean;
  /** Conditional block id, e.g. `a2.b6`. */
  block: string;
}

export interface StepQuest {
  /** exile-leveling quest id (e.g. `a1q7`). */
  id: string;
  name: string;
  /** NPC who takes the hand-in (exile-leveling `quest_npc`). */
  npc?: string;
}

export interface RouteHint {
  text: string;
  /** Minimap direction in degrees, 0 = up, clockwise. */
  direction?: number;
}

export interface RouteStep {
  /** Stable within a dataset version: `a<act>.<nnn>`. */
  id: string;
  act: number;
  /** Area the player is in when doing this step (game area id). */
  area: string;
  kind: StepKind;
  /** Rendered instruction (real area / quest names). */
  text: string;
  when?: StepCondition;
  /** Areas entered by this step, in order (the last one is where you end up). */
  enters?: string[];
  waypointTo?: string;
  quests?: StepQuest[];
  kills?: string[];
  /** Quest items taken or used. */
  items?: string[];
  arena?: string;
  labyrinth?: string;
  /** Part of a trip to run this Labyrinth (normal / cruel / merciless); skipped when trials are off. */
  labTrip?: string;
  /** Opens a town portal here (`set`) or takes one (`use`: to town, or from town back to where it was opened). */
  portal?: "set" | "use";
  hints: RouteHint[];
  recommendedLevel?: string;
}

export interface RouteBlock {
  act: number;
  flag: RouteFlag;
  negate: boolean;
  /** Contains a Trial of Ascendancy. */
  trial: boolean;
  /** Quests handed in inside the block. */
  quests: string[];
}

/** A quest of Acts 1–10 (exile-leveling quests.json, from the game files). */
export interface RouteQuest {
  name: string;
  act: number;
  /** NPCs who give its rewards. */
  npcs: string[];
  /** Book item it rewards (`Book-a1q7` = Book of Skill / Regrets), or null. */
  book: string | null;
  /** Number of class-specific gem choices it rewards (0 = no gem reward). */
  gemRewards: number;
  /** Gems it unlocks at vendors. */
  vendorGems: number;
  /** Handed in somewhere in the route (any option). */
  onRoute: boolean;
}

export interface RouteData {
  steps: RouteStep[];
  blocks: Record<string, RouteBlock>;
  quests: Record<string, RouteQuest>;
  /** Areas the route uses outside Acts 1–10 (Aspirants' Plaza, Karui Shores). */
  extraAreas: Record<string, { name: string; act: number; town: boolean }>;
}

export interface RouteMeta {
  game: "poe1";
  patch: string;
  counts: { steps: number; acts: number };
  flags: RouteFlag[];
  source: {
    id: "exile-leveling";
    name: string;
    url: string;
    author: string;
    license: string;
    version: string | null;
    date: string | null;
    verification: Verification;
  };
}

// ---------------------------------------------------------------- quests & rewards

/** What a quest matters for (a quest can be several). */
export type QuestCategory =
  | "main" // main campaign progression
  | "passive" // Book of Skill
  | "refund" // Book of Regrets (passive respec points)
  | "gem" // skill gem reward
  | "ascendancy" // Trials of Ascendancy / Labyrinth
  | "pantheon"
  | "optional";

export type RewardType = "passive-points" | "respec-points" | "bandit-choice" | "pantheon";

export type BanditChoice = "kill" | "alira" | "kraityn" | "oak";

/** One permanent reward the guardian watches. */
export interface CampaignReward {
  /** Stable id, e.g. `passive.a1q7`. */
  id: string;
  type: RewardType;
  act: number;
  /** Quest name exactly as the game prints it in `/passives` (for passive points). */
  quest: string;
  /** exile-leveling quest id, when the quest is in the route data. */
  questId: string | null;
  /** Points for passive / respec rewards; null when not verified. */
  points: number | null;
  /** Area where the objective is done (game area id), when known. */
  objectiveArea: string | null;
  /** Short objective in our own words. */
  objective: string;
  /** NPC who gives the reward, when known. */
  npc: string | null;
  /** Rewards that must be done first (game gates, not route order). */
  requires: string[];
  /** Needed for the full count of quest passive points (24 with Kill all, 23 otherwise). */
  requiredForPoints: boolean;
  /** On the default route (otherwise optional content). */
  onDefaultRoute: boolean;
  /** The reward itself: that it exists, its quest name and its amount. */
  provenance: Provenance;
  /** Objective, area and NPC (often a different, community source). */
  details: Provenance;
  /** Pantheon power unlocked by this quest's boss. */
  pantheon?: { god: string; tier: "major" | "minor" };
}
